/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const lines = [];
rl.on("line", (line) => {
  lines.push(line);

  if (lines.length === 2) {
    const m = lines[0] - 0;
    const p = lines[1].split(" ").map(Number);
    console.log(getResult(m, p));
    lines.length = 0;
  }
});

function getResult(m, p) {
  const dp = new Array(m + 1).fill(0);

  for (let i = 0; i <= p.length; i++) {
    for (let j = 0; j <= m; j++) {
      if (i == 0 || j == 0 || j < i) continue;
      dp[j] = Math.max(dp[j], dp[j - i] + p[i - 1]);
    }
  }

  return dp[m];
}

Java:
import java.util.Arrays;
import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    int m = Integer.parseInt(sc.nextLine());
    Integer[] p =
        Arrays.stream(sc.nextLine().split(" ")).map(Integer::parseInt).toArray(Integer[]::new);

    System.out.println(getResult(m, p));
  }

  public static int getResult(int m, Integer[] p) {
    int[] dp = new int[m + 1];

    for (int i = 0; i <= p.length; i++) {
      for (int j = 0; j <= m; j++) {
        if (i == 0 || j == 0 || j < i) continue;
        dp[j] = Math.max(dp[j], dp[j - i] + p[i - 1]);
      }
    }

    return dp[m];
  }
}
